                gMain.state++;
            break;
        case 8:
            InitPyramidBagWindows();
            gMain.state++;
            break;
        case 9:
            UpdatePyramidBagList();
            UpdatePyramidBagCursorPos();
            InitPyramidBagScroll();
            gMain.state++;
            break;
        case 10:
            SetBagItemsListTemplate();
            gMain.state++;
            break;
        case 11:
            CreatePyramidBagInputTask();
            gMain.state++;
            break;
        case 12:
            CreatePyramidBagSprite();
            gMain.state++;
            break;
        case 13:
            AddScrollArrows();
            gMain.state++;
            break;
