        PrintMenuActionText_SingleRow(OpenMenuActionWindowById(MENU_WIN_1x1));
    else if (gPyramidBagMenu->menuActionsCount == 2)
        PrintMenuActionText_SingleRow(OpenMenuActionWindowById(MENU_WIN_1x2));
