HandleMenuActionInput_SingleRow.body:
if (MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
    {
        s32 id = Menu_ProcessInputNoWrap();
        switch (id)
        {
        case MENU_NOTHING_CHOSEN:
            break;
